import java.util.*;
import java.io.*;

public class MaxFlowSolver {

    static final int MAXN = 300;
    static final int INF = 1000000000;

    static class Edge {
        int to, rev, f, cap;

        Edge(int to, int rev, int f, int cap) {
            this.to = to;
            this.rev = rev;
            this.f = f;
            this.cap = cap;
        }
    }

    static List<Edge>[] adj = new ArrayList[MAXN];
    static int[] dis = new int[MAXN];
    static int[] ptr = new int[MAXN];

    static int src, dst;

    static boolean bfs() {
        Arrays.fill(dis, -1);
        dis[src] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(src);
        while (!q.isEmpty() && dis[dst] == -1) {
            int u = q.poll();
            for (Edge e : adj[u]) {
                int v = e.to;
                if (dis[v] == -1 && e.f < e.cap) {
                    dis[v] = dis[u] + 1;
                    q.offer(v);
                }
            }
        }
        return dis[dst] != -1;
    }

    static int dfs(int u, int f) {
        if (u == dst || f == 0)
            return f;
        for (int &i = ptr[u]; i < adj[u].size(); i++) {
            Edge e = adj[u].get(i);
            int v = e.to;
            if (dis[v] != dis[u] + 1)
                continue;
            int df = dfs(v, Math.min(f, e.cap - e.f));
            if (df > 0) {
                e.f += df;
                adj[v].get(e.rev).f -= df;
                return df;
            }
        }
        return 0;
    }

    static int mf() {
        int res = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int df;
            while ((df = dfs(src, INF)) > 0)
                res += df;
        }
        return res;
    }

    static void add_edge(int u, int v, int c, int rc) {
        if (rc == -1)
            rc = 0;
        Edge a = new Edge(v, adj[v].size(), 0, c);
        Edge b = new Edge(u, adj[u].size(), 0, rc);
        adj[u].add(a);
        adj[v].add(b);
    }

    static int[] dx = {-1, 0, 0, 1};
    static int[] dy = {0, -1, 1, 0};

    static int n, m;
    static char[][] lab;
    static char[][] rea;
    static int[][] obs, tim, dii;

    static class Pair {
        int first, second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static void gbfs(int r, int c, int[][] dis, boolean chk) {
        for (int i = 0; i < n; i++)
            Arrays.fill(dis[i], -1);
        dis[r][c] = 0;
        Queue<Pair> q = new LinkedList<>();
        q.offer(new Pair(r, c));
        while (!q.isEmpty()) {
            Pair p = q.poll();
            if (chk && dis[p.first][p.second] == tim[p.first][p.second])
                continue;
            for (int i = 0; i < 4; i++) {
                int nr = p.first + dx[i];
                int nc = p.second + dy[i];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || dis[nr][nc] != -1 || obs[nr][nc] != 0)
                    continue;
                if (chk && tim[nr][nc] > -1 && dis[p.first][p.second] + 1 > tim[nr][nc])
                    continue;
                dis[nr][nc] = dis[p.first][p.second] + 1;
                q.offer(new Pair(nr, nc));
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String[] nms = br.readLine().split(" ");
        n = Integer.parseInt(nms[0]);
        m = Integer.parseInt(nms[1]);

        lab = new char[n][];
        rea = new char[n][];
        for (int i = 0; i < n; i++) {
            lab[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            rea[i] = br.readLine().toCharArray();
        }

        obs = new int[n][n];
        tim = new int[n][n];
        dii = new int[n][n];

        for (int i = 0; i < n; i++) {
            Arrays.fill(obs[i], 0);
            Arrays.fill(tim[i], -1);
            Arrays.fill(dii[i], -1);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                obs[i][j] = (lab[i][j] == 'Y') ? 1 : 0;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (lab[i][j] == 'Z')
                    gbfs(i, j, tim, false);
            }
        }

        src = 2 * n * n + 5;
        dst = src + 1;

        for (int i = 0; i < adj.length; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                if (lab[x][y] == 'Z' || lab[x][y] == 'Y')
                    continue;

                add_edge(src, n * x + y, lab[x][y] - '0', -1);
                add_edge(n * n + n * x + y, dst, rea[x][y] - '0', -1);
                gbfs(x, y, dii, true);

                for (int xp = 0; xp < n; xp++) {
                    for (int yp = 0; yp < n; yp++) {
                        if (dii[xp][yp] != -1 && dii[xp][yp] <= m) {
                            add_edge(n * x + y, n * n + n * xp + yp, INF, -1);
                        }
                    }
                }
            }
        }

        System.out.println(mf());
    }
}
